import { pool } from "../config/db.js";

export async function listExams(req, res, next) {
  try {
    const classId = req.query.class_id ? Number(req.query.class_id) : null;
    const section = req.query.section ? String(req.query.section) : null;

    const where = [];
    const values = [];
    if (classId) {
      values.push(classId);
      where.push(`e.class_id = $${values.length}`);
    }
    if (section) {
      values.push(section);
      where.push(`c.section = $${values.length}`);
    }

    const result = await pool.query(
      `select
        e.*,
        c.class_name,
        c.section
      from exams e
      join classes c on c.id = e.class_id
      ${where.length ? `where ${where.join(" and ")}` : ""}
      order by e.date desc, e.id desc`,
      values,
    );
    return res.json({ exams: result.rows });
  } catch (e) {
    return next(e);
  }
}

export async function createExam(req, res, next) {
  try {
    const { name, class_id, date } = req.validated.body;

    const klass = await pool.query("select class_name from classes where id = $1", [class_id]);
    if (klass.rowCount === 0) return res.status(400).json({ error: "class_id not found" });
    const className = String(klass.rows[0].class_name);

    const created = await pool.query(
      `insert into exams (name, class_id, class, date)
       values ($1, $2, $3, $4)
       returning *`,
      [name, class_id, className, date],
    );
    return res.status(201).json({ exam: created.rows[0] });
  } catch (e) {
    return next(e);
  }
}

